import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { ChevronDown, Search, Menu, X } from 'lucide-react';

export default function Header() {
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [selectedLocation, setSelectedLocation] = useState('Lefkosia');
  const [searchQuery, setSearchQuery] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false); // Modal visibility state

  const navigate = useNavigate();

  const toggleDropdown = () => setIsDropdownOpen((prev) => !prev);
  const toggleMobileMenu = () => setIsMobileMenuOpen((prev) => !prev);
  const handleLocationChange = (location) => {
    setSelectedLocation(location);
    setIsDropdownOpen(false);
  };
  const handleSearch = (e) => {
    e.preventDefault();
  };

  const toggleModal = () => setIsModalOpen((prev) => !prev); // Toggle modal

  return (
    <header className="bg-white mt-0">
      <div className="container mx-auto px-4 py-4 flex items-center">
        {/* Left Section: Logo */}
        <div className="flex items-center space-x-6">
          <Link to="/">
            <img src="/k1.jpeg" alt="Logo" className="w-[120px] h-auto" />
          </Link>
          {/* Dropdown for Location */}
          <div className="relative hidden md:block">
            <button
              onClick={toggleDropdown}
              className="flex items-center text-gray-600 hover:text-gray-800 space-x-2"
            >
              <span className="text-red-600">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="w-5 h-5"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M12 11c0 1.657-1.343 3-3 3s-3-1.343-3-3 1.343-3 3-3 3 1.343 3 3zM12 11v3m6-6a9 9 0 11-6-6c1.488-.276 2.815 0.374 3.514 1.47M6.343 6.343l1.414 1.414M15.88 15.88a3 3 0 004.243 0 3 3 0 00.273-4.01m0 0l-1.414-1.414M18 18v3m0 0h-3m3 0a9 9 0 11-9-9m6-6v3"
                  />
                </svg>
              </span>
              {selectedLocation} <ChevronDown size={16} />
            </button>
            {/* Dropdown Menu */}
            {isDropdownOpen && (
              <div className="absolute mt-2 bg-white shadow-lg rounded-md w-48 z-50 border border-gray-200">
                <ul>
                  {['Lefkosia', 'Magusa', 'Girne', 'Guzelyurt', 'Lefke', 'Iskele'].map((location) => (
                    <li
                      key={location}
                      onClick={() => handleLocationChange(location)}
                      className="px-4 py-2 hover:bg-gray-100 cursor-pointer"
                    >
                      {location}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        </div>

        {/* Middle Section: Search Bar */}
        <div className="flex-grow mx-6">
          <form onSubmit={handleSearch} className="flex items-center bg-gray-100 rounded-md">
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Find Cars, Mobile Phones and more..."
              className="flex-grow p-2 bg-transparent focus:outline-none"
            />
            <Link to={`/search?query=${searchQuery}`} className="p-2 bg-red-500 text-white rounded-r-md">
              <Search size={24} />
            </Link>
          </form>
        </div>

        {/* Right Section: Options */}
        <div className="flex items-center space-x-4">
          <button
            onClick={toggleMobileMenu}
            className="block md:hidden text-gray-600 hover:text-gray-800"
          >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
          <button className="hidden md:block text-gray-600 border-b-2 border-transparent hover:border-red-500">
            Sign up
          </button>
          <button
            onClick={toggleModal} // Show modal when Login is clicked
            className="hidden md:block text-gray-600 border-b-2 border-transparent hover:border-red-500"
          >
            Login
          </button>
          <Link to="/sell" className="hidden md:block bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-700">
            Sell
          </Link>
        </div>
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50">
          <div className="bg-white rounded-lg p-6 w-96">
            <h2 className="text-xl font-bold mb-4">Login</h2>
            <form>
              <div className="mb-4">
                <label className="block text-gray-700">Email</label>
                <input
                  type="email"
                  className="w-full p-2 border border-gray-300 rounded-md focus:outline-none"
                />
              </div>
              <div className="mb-4">
                <label className="block text-gray-700">Password</label>
                <input
                  type="password"
                  className="w-full p-2 border border-gray-300 rounded-md focus:outline-none"
                />
              </div>
              <button
                type="button"
                onClick={toggleModal}
                className="bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-700 w-full"
              >
                Login
              </button>
            </form>
          </div>
        </div>
      )}
    </header>
  );
}
